#include <Loop.hpp>
#include <cmath>
#include <complex>
#include <iostream>
#include <scalarselect_mod.hpp>

using namespace scalarselect_mod;

complex loopI3(double p1, double p2, double p3, double m1, double m2, double m3, double mu2, int ep) {

  complex loopI3_res, resQCDLoop, resOneLOop;
  complex result[3];

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli3(p1, p2, p3, m1, m2, m3, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI3_res = resQCDLoop;
    return loopI3_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-9 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-9) {
      std::cout << "loopI3: " << p1 << ", " << p2 << ", " << p3 << ", " << m1 << ", " << m2 << ", " << m3 << ", " << mu2 << ", " << ep << std::endl;
      std::cout << "QCDLoop: " << resQCDLoop << std::endl;
      std::cout << "OneLOop: " << resOneLOop << std::endl;
      std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI3_res;
}

complex loopI3(double p1, double p2, double p3, complex m1, complex m2, complex m3, double mu2, int ep) {

  complex loopI3_res, resQCDLoop, resOneLOop;
  complex result[3];

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli3c(p1, p2, p3, m1, m2, m3, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI3_res = resQCDLoop;
    return loopI3_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-12 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-12) {
      std::cout << "loopI3: " << p1 << ", " << p2 << ", " << p3 << ", " << m1 << ", " << m2 << ", " << m3 << ", " << mu2 << ", " << ep << std::endl;
      std::cout << "QCDLoop: " << resQCDLoop << std::endl;
      std::cout << "OneLOop: " << resOneLOop << std::endl;
      std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI3_res;
}

extern "C" {
  complex loopI3_wrapper(double p1, double p2, double p3, double m1, double m2, double m3, double mu2, int ep) {
    return loopI3(p1, p2, p3, m1, m2, m3, mu2, ep);
  }

  complex loopI3c_wrapper(double p1, double p2, double p3, complex m1, complex m2, complex m3, double mu2, int ep) {
    return loopI3(p1, p2, p3, m1, m2, m3, mu2, ep);
  }
}

